<script setup>
import { ref, onMounted } from 'vue'
const me=ref(null),csrf=ref(null),username=ref('admin'),password=ref(''),error=ref(''),busy=ref(false)
const documents=ref([]),history=ref([]),current=ref(null),question=ref(''),selectedFile=ref(null),source=ref(null),tab=ref('ask')
const docPage=ref(0),docMore=ref(false),historyPage=ref(0),historyMore=ref(false),editing=ref(null),replacement=ref(null),deleting=ref(null),versions=ref(null)
const labels={ANSWERED:'已有引用',INSUFFICIENT:'资料不足',FAILED:'本次失败',INDEXED:'索引完成',IMPORTING:'导入中',PENDING:'待处理',CANCELLED:'已取消',SUPERSEDED:'已被取代',NONE:'无需清理',DONE:'已清理',RUNNING:'清理中'}
async function token(){const r=await fetch('/api/csrf',{signal:AbortSignal.timeout(10000)});if(!r.ok)throw new Error('无法获取登录凭证');csrf.value=await r.json()}
async function api(path,options={}){
  const headers={...options.headers}
  if(options.method&&options.method!=='GET'){if(!csrf.value)await token();headers[csrf.value.headerName]=csrf.value.token}
  let r
  try{r=await fetch('/api'+path,{...options,headers,signal:AbortSignal.timeout(180000)})}
  catch(e){throw new Error(e.name==='TimeoutError'?'请求等待超时，服务端结果尚未确认；请刷新状态再手动重试。':'网络连接失败，请恢复连接后刷新状态。')}
  const data=r.status===204?null:await r.json()
  if(!r.ok){if(r.status===401){me.value=null;source.value=null;current.value=null;history.value=[]}throw new Error(data?.message||`请求失败 ${r.status}`)}
  return data
}
async function run(fn){if(busy.value)return;busy.value=true;error.value='';try{await fn()}catch(e){error.value=e.message}finally{busy.value=false}}
async function loadDocs(page=docPage.value){const p=await api(`/documents?page=${page}&size=12`);documents.value=p.items;docPage.value=p.page;docMore.value=p.hasMore}
async function loadHistory(page=historyPage.value){const p=await api(`/chats?page=${page}&size=10`);history.value=p.items;historyPage.value=p.page;historyMore.value=p.hasMore}
async function refresh(){await Promise.all([loadDocs(),loadHistory()]);if(current.value)current.value=await api('/chats/'+current.value.chat.id)}
async function login(){await run(async()=>{await token();await api('/login',{method:'POST',body:new URLSearchParams({username:username.value,password:password.value})});password.value='';await token();me.value=await api('/me');docPage.value=0;historyPage.value=0;await refresh()})}
async function logout(){await run(async()=>{await api('/logout',{method:'POST'});me.value=null;history.value=[];documents.value=[];current.value=null;source.value=null;versions.value=null;editing.value=null;deleting.value=null;await token()})}
async function mutation(path,options){const d=await api(path,options);await refresh();if(d.status==='FAILED')error.value=d.failure;else if(d.cleanupPending)error.value='资料状态已更新，仍有向量待清理。可查看版本记录并手动重试清理。'}
async function upload(){if(!selectedFile.value)return;await run(async()=>{const body=new FormData();body.append('file',selectedFile.value);docPage.value=0;await mutation('/admin/documents',{method:'POST',body})})}
async function replace(){if(!editing.value||!replacement.value)return;await run(async()=>{const d=editing.value,body=new FormData();body.append('file',replacement.value);body.append('expectedVersion',d.activeVersion??0);await mutation(`/admin/documents/${d.id}/versions`,{method:'POST',body});editing.value=null;replacement.value=null})}
async function remove(){const d=deleting.value;await run(async()=>{await mutation(`/admin/documents/${d.id}?expectedVersion=${d.activeVersion??0}`,{method:'DELETE'});deleting.value=null;source.value=null})}
async function retry(d){await run(()=>mutation(`/admin/documents/${d.id}/versions/${d.version}/retry`,{method:'POST'}))}
async function cleanup(d){await run(()=>mutation(`/admin/documents/${d.id}/cleanup`,{method:'POST'}))}
async function ask(){if(!question.value.trim())return;await run(async()=>{source.value=null;current.value=await api('/chats',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({question:question.value})});historyPage.value=0;await refresh()})}
async function openChat(item){await run(async()=>{current.value=await api('/chats/'+item.chat.id);source.value=null;question.value=current.value.chat.question})}
async function inspect(c){await run(async()=>{source.value={...await api(`/chunks/${c.id}`),quote:c.quote,full:false}})}
async function fullSource(){await run(async()=>{const s=source.value;source.value={...s,...await api(`/documents/${s.documentId}/versions/${s.version}`),full:true}})}
async function openDocument(d){await run(async()=>{source.value={...await api(`/documents/${d.id}/versions/${d.activeVersion}`),full:true}})}
async function openVersions(d){await run(async()=>{versions.value={filename:d.filename,items:await api(`/admin/documents/${d.id}/versions`)}})}
onMounted(async()=>{try{await token();me.value=await api('/me');await refresh()}catch(e){if(me.value)error.value=e.message}})
</script>

<template>
  <div class="shell" @keydown.esc="source=null;versions=null">
    <header><a class="brand" href="/">知页 <span>JAVA KNOWLEDGE</span></a><div class="header-right"><span class="pill">学习项目 · M2</span><span v-if="me">{{ me.username }} · {{ me.admin?'管理员':'读者' }}</span><button v-if="me" class="quiet" @click="logout" :disabled="busy">退出</button></div></header>
    <div v-if="error" role="alert" class="error">{{ error }}</div>
    <main v-if="!me" class="login"><p class="eyebrow">SHARED KNOWLEDGE / PRIVATE CONVERSATIONS</p><h1>从资料中寻找答案。</h1><p class="muted">团队共用一份知识库，问答记录仅本人可见。<br>所有示例资料均为自编模拟内容。</p><form @submit.prevent="login"><label>账号<input v-model="username" autocomplete="username" required maxlength="40"></label><label>密码<input v-model="password" type="password" autocomplete="current-password" required maxlength="72"></label><button :disabled="busy">{{ busy?'正在登录…':'登录知识库' }}</button><small>演示账号：admin / reader / reader2。密码由本机环境变量配置。</small></form></main>
    <template v-else>
      <div class="notice" :class="{mock:me.mode==='mock'}"><strong>{{ me.mode==='mock'?'MOCK 流程演示':'真实模型模式' }}</strong><span>{{ me.notice }}</span></div>
      <nav><button :class="{active:tab==='ask'}" @click="tab='ask'">知识问答</button><button :class="{active:tab==='docs'}" @click="tab='docs'">共享资料</button><button class="refresh" :disabled="busy" @click="run(refresh)">刷新状态</button></nav>
      <main v-if="tab==='ask'" class="workspace">
        <aside><div class="section-head"><h2>我的记录</h2><button class="quiet" @click="current=null;source=null;question=''" :disabled="busy">新问题</button></div><p v-if="!history.length" class="muted">还没有问答。试着提出一个具体问题。</p><button v-for="item in history" :key="item.chat.id" class="history" :class="{selected:current?.chat.id===item.chat.id}" @click="openChat(item)" :disabled="busy"><span>{{ item.chat.question }}</span><small>{{ labels[item.chat.status] }} · {{ item.chat.mode.toUpperCase() }}</small></button><div class="pager"><button class="quiet" :disabled="busy||historyPage===0" @click="run(()=>loadHistory(historyPage-1))">上一页</button><small>{{ historyPage+1 }}</small><button class="quiet" :disabled="busy||!historyMore" @click="run(()=>loadHistory(historyPage+1))">下一页</button></div><small>每次提问独立检索，不自动续接上一轮上下文。打开记录会重新核验引用状态。</small></aside>
        <section class="chat-panel"><p class="eyebrow">ASK WITH EVIDENCE</p><h1>让每个答案，都有出处。</h1><p class="muted">先导入资料，再问入职、设备或报销问题。</p><form class="ask-form" @submit.prevent="ask"><label for="question">你的问题</label><textarea id="question" v-model="question" maxlength="1000" rows="3" placeholder="例如：模拟网约车单次报销上限是多少？" required></textarea><div class="form-foot"><small>{{ question.length }}/1000 · 最多 {{ me.topK }} 个有效片段</small><button :disabled="busy||!question.trim()">{{ busy?'正在处理…':'查询资料' }}</button></div></form>
          <article v-if="current" class="answer"><div class="section-head"><span class="pill">{{ labels[current.chat.status] }}</span><small>{{ current.chat.mode.toUpperCase() }} · {{ current.chat.latencyMs }} ms</small></div><h3>{{ current.chat.question }}</h3><p v-if="current.citations.some(c=>!c.valid)" class="failure">这条历史回答包含失效引用，不能作为当前规则使用。请重新提问。</p><p class="prewrap">{{ current.chat.answer }}</p><p v-if="current.chat.status==='INSUFFICIENT'" class="muted">可把问题缩小到具体制度或设备，或请管理员补充资料后再问。</p><button v-if="current.chat.status==='FAILED'||current.citations.some(c=>!c.valid)" @click="question=current.chat.question;ask()" :disabled="busy">手动重新提问</button><div v-if="current.citations.length" class="citations"><h3>核对原文</h3><div v-for="(c,i) in current.citations" :key="c.id"><button @click="inspect(c)" :disabled="busy||!c.valid"><b>[{{ i+1 }}] {{ c.filename }}</b><span>{{ c.section }} · v{{ c.version }}{{ c.valid?'':' · 引用已失效' }}</span></button><blockquote v-if="c.valid&&c.quote">{{ c.quote }}</blockquote><small v-else-if="c.valid">旧记录未保存摘句，可打开原文核对。</small></div><small>引用和摘句已通过来源校验；结论是否得到充分支持仍需人工核对。</small></div></article>
          <div v-else class="empty"><span>01 / 提问</span><span>02 / 查找片段</span><span>03 / 核对引用</span><p>没有足够依据时应提示资料不足。MOCK 只摘录检索结果，不理解语义，可能返回无关片段；它不代表真实模型的回答或拒答能力。</p></div>
        </section>
      </main>
      <main v-else class="documents"><p class="eyebrow">TEAM LIBRARY</p><h1>共享资料</h1><p class="muted">支持 UTF-8 Markdown / TXT。新版本索引成功后发布；停用立即影响检索，向量清理失败可重试。</p>
        <form v-if="me.admin" class="upload" @submit.prevent="upload"><label>上传模拟资料<input type="file" accept=".md,.txt,text/plain,text/markdown" @change="selectedFile=$event.target.files[0]" required></label><small>最大 256 KiB · 最多 100 个片段<br>samples 内共 12 份自编模拟资料</small><button :disabled="busy||!selectedFile">{{ busy?'正在处理…':'导入并建立索引' }}</button></form>
        <form v-if="editing" class="upload" @submit.prevent="replace"><label>替换 {{ editing.filename }} · 当前 v{{ editing.activeVersion??0 }}<input type="file" accept=".md,.txt" @change="replacement=$event.target.files[0]" required></label><small>导入失败时保留当前可用版本。</small><button :disabled="busy||!replacement">提交新版本</button><button type="button" class="quiet" @click="editing=null" :disabled="busy">取消</button></form>
        <div v-if="deleting" class="error"><p>确认停用「{{ deleting.filename }}」？读者将无法检索它，已有引用会失效。M2 不提供恢复入口。</p><button class="danger" @click="remove" :disabled="busy">确认停用并清理</button> <button class="quiet" @click="deleting=null" :disabled="busy">取消</button></div>
        <div class="doc-grid"><article v-for="d in documents" :key="d.id"><span class="pill">{{ d.deleted?'已停用':d.available?'当前可检索':'尚未发布' }}</span><h3>{{ d.filename }}</h3><p>当前版本 {{ d.activeVersion??'无' }} · 最新 v{{ d.version }}<br>{{ labels[d.status]||d.status }} / {{ d.stage }}</p><small class="mono">{{ d.id }}</small><p v-if="d.failure" class="failure">{{ d.failure }}</p><p v-if="d.cleanupPending" class="failure">{{ d.cleanupPending }} 个版本待清理<br>{{ d.cleanupFailure||'等待导入尝试结束或清理重试' }}</p><div class="actions"><button v-if="d.available&&!d.deleted" class="quiet" @click="openDocument(d)" :disabled="busy">查看当前原文</button><template v-if="me.admin"><button class="quiet" @click="openVersions(d)" :disabled="busy">版本记录</button><button v-if="!d.deleted" class="quiet" @click="editing={...d};replacement=null;deleting=null" :disabled="busy">替换版本</button><button v-if="!d.deleted&&d.status!=='INDEXED'" @click="retry(d)" :disabled="busy">重试导入 v{{ d.version }}</button><button v-if="!d.deleted" class="quiet danger-text" @click="deleting={...d};editing=null" :disabled="busy">停用删除</button><button v-if="d.cleanupPending" @click="cleanup(d)" :disabled="busy">重试向量清理</button></template></div></article></div>
        <div class="pager"><button class="quiet" :disabled="busy||docPage===0" @click="run(()=>loadDocs(docPage-1))">上一页</button><small>第 {{ docPage+1 }} 页</small><button class="quiet" :disabled="busy||!docMore" @click="run(()=>loadDocs(docPage+1))">下一页</button></div><p v-if="!documents.length" class="muted">本页暂无资料。</p>
      </main>
      <footer>模型 {{ me.model }} / Embedding {{ me.embedding }} · 所有示例制度均为虚构</footer>
    </template>
    <div v-if="source" class="overlay" @click.self="source=null"><section role="dialog" aria-modal="true" aria-labelledby="source-title" class="source"><div class="section-head"><span class="pill">{{ source.full?'文件原文':'引用片段' }} · v{{ source.version }}</span><button class="quiet" @click="source=null" autofocus>关闭</button></div><h2 id="source-title">{{ source.filename }}</h2><h3 v-if="!source.full">{{ source.section }}</h3><small class="mono">文档 {{ source.documentId }}<br v-if="source.id"><span v-if="source.id">片段 {{ source.id }}</span></small><blockquote v-if="source.quote">回答引用的摘句：{{ source.quote }}</blockquote><pre>{{ source.content }}</pre><button v-if="!source.full" @click="fullSource" :disabled="busy">查看完整文件</button></section></div>
    <div v-if="versions" class="overlay" @click.self="versions=null"><section role="dialog" aria-modal="true" aria-labelledby="versions-title" class="source"><div class="section-head"><h2 id="versions-title">{{ versions.filename }} · 版本记录</h2><button class="quiet" @click="versions=null">关闭</button></div><article v-for="v in versions.items" :key="v.version" class="version-row"><h3>v{{ v.version }} · {{ v.active?'当前生效':labels[v.status]||v.status }}</h3><p>{{ v.sourceFilename }} · {{ v.stage }}<br>向量清理：{{ labels[v.cleanupStatus]||v.cleanupStatus }}</p><p v-if="v.failure||v.cleanupFailure" class="failure">{{ v.failure }} {{ v.cleanupFailure }}</p></article><small>旧版本仅保留审计元数据和历史引用，不作为当前资料提供给读者。</small></section></div>
  </div>
</template>
